{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    required_fields = {"nodes", "required_symbols"}
    if set(case) < required_fields:
        raise ValueError("missing required fields")
    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError("invalid field types")
    if any(not isinstance(symbol, str) for symbol in required_symbols):
        raise ValueError("required_symbols must contain strings")
    if not nodes:
        raise ValueError("nodes must not be empty")

    required_node_fields = {"id", "parent", "symbol", "depth", "removable", "utility"}
    by_id = {}
    positions = {}
    for position, node in enumerate(nodes):
        if not isinstance(node, dict) or set(node) < required_node_fields:
            raise ValueError("invalid node")
        node_id = node["id"]
        if not isinstance(node_id, str) or node_id in by_id:
            raise ValueError("node ids must be unique strings")
        if not isinstance(node["parent"], (str, type(None))):
            raise ValueError("invalid parent")
        if not isinstance(node["symbol"], str):
            raise ValueError("invalid symbol")
        if isinstance(node["depth"], bool) or not isinstance(node["depth"], int) or node["depth"] < 0:
            raise ValueError("invalid depth")
        if not isinstance(node["removable"], bool):
            raise ValueError("invalid removable flag")
        if isinstance(node["utility"], bool) or not isinstance(node["utility"], (int, float)):
            raise ValueError("invalid utility")
        by_id[node_id] = node
        positions[node_id] = position

    roots = [node for node in nodes if node["parent"] is None]
    if len(roots) != 1:
        raise ValueError("tree must have exactly one root")
    root = roots[0]
    children = {node_id: [] for node_id in by_id}
    for node in nodes:
        parent = node["parent"]
        if parent is not None:
            if parent not in by_id:
                raise ValueError("parent must reference an existing node")
            children[parent].append(node["id"])
    if root["depth"] != 0:
        raise ValueError("root depth must be zero")
    for node in nodes:
        if node["parent"] is not None and node["depth"] != by_id[node["parent"]]["depth"] + 1:
            raise ValueError("invalid node depth")

    reachable = set()
    stack = [root["id"]]
    while stack:
        node_id = stack.pop()
        if node_id in reachable:
            raise ValueError("tree contains a cycle")
        reachable.add(node_id)
        stack.extend(reversed(children[node_id]))
    if reachable != set(by_id):
        raise ValueError("all nodes must belong to the tree")

    retained = set(by_id)
    removal_order = []
    required = set(required_symbols)
    candidates = sorted(nodes, key=lambda node: (-node["depth"], node["id"]))
    for node in candidates:
        node_id = node["id"]
        if node_id == root["id"] or not node["removable"] or node["symbol"] in required:
            continue
        if any(child in retained for child in children[node_id]):
            continue
        remaining_symbols = {by_id[retained_id]["symbol"] for retained_id in retained if retained_id != node_id}
        if not required.issubset(remaining_symbols):
            continue
        retained.remove(node_id)
        removal_order.append(node_id)

    return {
        "removed_node_ids": removal_order,
        "retained_node_ids": sorted(retained)
    }"}
